    for (let i = 0; i < nw; i++) { const s = 30 + rnd(i, seed + 20) * (violent ? 140 : 100), x = rnd(i, seed + 21) * W, yy = rnd(i, seed + 22) * H;
      if (rnd(i, seed + 23) < 0.25) { c.font = `${s}px serif`; c.fillText('🥔', x, yy); continue; }
      c.font = `400 ${s}px "Major Mono Display", monospace`; const w = gw(i + f * 3);
      c.fillStyle = '#e03ccf'; c.fillText(w, x + 4, yy); c.fillStyle = '#2a0f63'; c.fillText(w, x - 4, yy + 2); c.fillStyle = rnd(i, seed + 24) < 0.5 ? '#9a52ff' : '#c9a7ff'; c.fillText(w, x, yy); }
    // scanlines
